export async function listTools() {
  return [
    {
      name: 'run_with_progress',
      description: 'Run a task reporting monotonic progress from 0 to 1.',
      inputSchema: {
        type: 'object',
        properties: {
          steps: {
            type: 'integer',
            description: 'Number of steps to run (positive integer).',
            exclusiveMinimum: 0
          }
        },
        required: ['steps']
      }
    }
  ];
}

export async function callTool(name, args = {}, options = {}) {
  if (name !== 'run_with_progress') {
    const err = new Error(`Unknown tool: ${name}`);
    err.code = -32602;
    throw err;
  }
  const steps = args.steps;
  if (!Number.isInteger(steps) || steps <= 0) {
    const err = new Error('steps must be a positive integer');
    err.code = -32602;
    throw err;
  }
  const onProgress = typeof options.onProgress === 'function' ? options.onProgress : null;
  for (let i = 0; i <= steps; i++) {
    const progress = i / steps;
    if (onProgress) onProgress(progress);
  }
  return {
    content: [{ type: 'text', text: 'completed' }]
  };
}
